package com.mcnex.conversation;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public final class KakaoVoiceProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View match=find(g.getChildAt(i),text);if(match!=null)return match;}}return null;}
 private void check(boolean ok,String label){if(!ok)throw new IllegalStateException(label);}
 public void onStart(){Bundle report=new Bundle();Dialog[] dialog={null};KakaoVoice[] voice={null};java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> error=new java.util.concurrent.atomic.AtomicReference<>("");try{MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->{dialog[0]=activity.kakaoQuestion(KakaoMemory.get(activity));check(find(dialog[0].getWindow().getDecorView(),"음성 질문")!=null,"voice button");Bundle b=new Bundle();b.putStringArrayList(android.speech.SpeechRecognizer.RESULTS_RECOGNITION,new ArrayList<>(Arrays.asList("  광학센서 회의 일정은 언제야?  ")));check(KakaoVoice.recognized(b).equals("광학센서 회의 일정은 언제야?"),"recognized text");check(KakaoVoice.recognized(null).isEmpty(),"empty result");check(KakaoVoice.error(9).contains("권한"),"permission error");check(KakaoVoice.error(13).contains("한국어"),"language error");voice[0]=new KakaoVoice(activity,new KakaoVoice.Callback(){public void text(String ignored){}public void state(boolean active,String message){if(message.startsWith("말씀해 주세요"))ready.countDown();if(!active&&message.contains("오류"))error.set(message);}});voice[0].start();});check(ready.await(8,java.util.concurrent.TimeUnit.SECONDS),"on-device microphone not ready: "+error.get());Thread.sleep(1000);runOnMainSync(()->{check(voice[0].active(),"session prematurely closed");voice[0].close();check(!voice[0].active(),"microphone release");dialog[0].dismiss();});report.putBoolean("ok",true);report.putString("result","voice button, Korean recognition text transfer, permission/language errors, actual on-device microphone ready and release passed; no transcript retained");}catch(Throwable e){report.putBoolean("ok",false);report.putString("error",e.toString());}finally{runOnMainSync(()->{if(voice[0]!=null)voice[0].close();if(dialog[0]!=null)dialog[0].dismiss();});}finish(report.getBoolean("ok")?-1:0,report);}
}
